"""Thin adapter over the authors' unmodified repo/TokenCore.py.

R3: the memory bank is fit on the word-level embeddings of every token of the
    normal training documents only (no anomalous token is ever stored).
R4: the token anomaly score is the distance to its nearest neighbour in that
    bank (sklearn NearestNeighbors default = Euclidean / L2, A1), higher = more
    anomalous.

The adapter keeps the README quick-start call pattern verbatim and raises if
the authors' API ever differs, so the driver is fixed and never the author file.
"""
import os
import sys

REPO = os.environ.get("TOKENCORE_REPO", "repo")


def _import_authors_class():
    if REPO not in sys.path:
        sys.path.insert(0, os.path.abspath(REPO))
    from TokenCore import TokenCore          # noqa: F401  (authors' file, unmodified)
    for name in ("TokenCore", "TextCore"):
        try:
            mod = __import__(name)
            return getattr(mod, name)
        except Exception:
            continue
    raise ImportError("could not import TokenCore from the authors' repo")


def fit_memory_bank(X_train):
    """Build the TokenCore memory bank from normal-training token embeddings."""
    cls = _import_authors_class()
    det = cls(n_neighbors=1)
    det.fit(X_train)
    return det


def token_scores(detector, X):
    """Nearest-neighbour distance per token embedding (Eq. 2, R4)."""
    for name in ("decision_function", "score_samples"):
        if hasattr(detector, name):
            s = getattr(detector, name)(X)
            return np.asarray(s).reshape(-1)
    raise AttributeError("authors' detector exposes neither decision_function nor score_samples")


