def verify_max_pooling(tokenizer, model, docs):
    """Hand-check Eq. 1: the word vector is the coordinate-wise max of its
    subword vectors, on a word that really splits into >1 subword."""
    import torch
    for doc in docs:
        words = doc["words"]
        enc = tokenizer(words, is_split_into_words=True, return_tensors="pt")
        wids = enc.word_ids(0)
        groups = {}
        for pos, w in enumerate(wids):
            if w is not None:
                groups.setdefault(w, []).append(pos)
        multi = [w for w, p in groups.items() if len(p) > 1]
        if not multi:
            continue
        with torch.no_grad():
            h = model(**enc).last_hidden_state[0].numpy()
        w = multi[0]
        manual = np.max(h[groups[w]], axis=0)
        X, _, _, _ = embed_bert.embed_documents([doc], tokenizer, model, strict=False)
        order = sorted(groups)                   # word units in document order
        pooled = X[order.index(w)]
        return {"checked": True, "doc_id": doc["doc_id"], "word": words[w],
                "n_subwords": len(groups[w]), "subwords": [tokenizer.convert_ids_to_tokens([enc['input_ids'][0][p].item()])[0] for p in groups[w]],
                "max_abs_error": float(np.abs(manual - pooled).max())}
    return {"checked": False}

